  const remMatch = trimmed.match(/^([0-9.]+)\s*rem$/i);
  if (remMatch) return Math.max(0, parseFloat(remMatch[1]) * 16);

  const emMatch = trimmed.match(/^([0-9.]+)\s*em$/i);
