import 'package:flutter/material.dart';

class ExhumaInfiniteMarquee extends StatefulWidget {
  final Widget child;
  final double speed;
  final double gap;

  const ExhumaInfiniteMarquee({
    super.key,
    required this.child,
    this.speed = 40.0,
    this.gap = 24.0,
  });

  @override
  State<ExhumaInfiniteMarquee> createState() => _ExhumaInfiniteMarqueeState();
}

class _ExhumaInfiniteMarqueeState extends State<ExhumaInfiniteMarquee>
    with SingleTickerProviderStateMixin {
  late final AnimationController _controller;

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(
      vsync: this,
      duration: const Duration(seconds: 15),
    )..repeat();
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return ClipRect(
      child: AnimatedBuilder(
        animation: _controller,
        builder: (context, _) {
          return SingleChildScrollView(
            scrollDirection: Axis.horizontal,
            physics: const NeverScrollableScrollPhysics(),
            child: Row(
              children: [
                widget.child,
                SizedBox(width: widget.gap),
                widget.child,
              ],
            ),
          );
        },
      ),
    );
  }
}
